sys_script_include.script:
var MSSAmendUtilsCore = Class.create();
MSSAmendUtilsCore.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    createBulkRecordForTradeAmend: function() { //Bulk Creation Functionality

        /*Artifacts involved: 
		MSSCUSTODY-5197
		1) Client Script - MSS Task Prepopulate Amend from Trade - To pass Trade ID and Set values for Field
		2) Script Include - MSSCustodyAmendUtils Method - getTradeFieldvalues - To retrive Values from trade and send back to client
		3) Client Script - MSS Task Create Bulk for Amend - To pass values from bulk extended fields and send to below script inlcude to create bulk record
		4) Script Include - MSSAmendUtilsCore - Create bulk record and map to the task
		This method is to prepropulate the amend fields for automated task when the outcome is selected as Amend related outcomes
    	Once the form is submitted, this method executes and populates thefield values from the trade
		*/

        try {

            var tasksysID = this.getParameter('sysparm_taskSysID');
            var assignmentGrp = this.getParameter('sysparm_assignmnetGrp');
            var assignedTo = this.getParameter('sysparm_assignedTo');
            var owningBussiness = this.getParameter('sysparm_tradeID');
            var taskOutcome = this.getParameter('sysparm_recOutcome');
            var bulkID = this.getParameter('sysparm_bulkID');

            var getowningBusiness = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            getowningBusiness.get(owningBussiness);
            var tradeMarket = getowningBusiness.owning_business;


            //inputs from bulk
            var securityID = this.getParameter('sysparm_securityID ');
            var tradeDate = this.getParameter('sysparm_tradeDate');
            var settlementDate = this.getParameter('sysparm_settlementDate');
            var dealPrice = this.getParameter('sysparm_dealPrice');
            var dealCurrency = this.getParameter('sysparm_dealCurrency');
            var settlementCurrency = this.getParameter('sysparm_settlementCurrency');
            var settlementAmount = this.getParameter('sysparm_settlementAmount');
            var counterPartyRef = this.getParameter('sysparm_counterPartyRef');
            var cusRef = this.getParameter('sysparm_cusRef');
            var locCode = this.getParameter('sysparm_locCode');
            var hmiIndicator = this.getParameter('sysparm_hmiIndicator');
            var scripholIndicator = this.getParameter('sysparm_scripholIndicator');
            var cashHoldIndicator = this.getParameter('sysparm_cashHoldIndicator');
            var gdiIncidcator = this.getParameter('sysparm_gdiIncidcator');
            var payMethod = this.getParameter('sysparm_payMethod');
            var switchIndicator = this.getParameter('sysparm_switchIndicator');
            var switchAcc = this.getParameter('sysparm_switchAcc');
            var susAccNum = this.getParameter('sysparm_susAccNum'); //new field
            var counterParCode = this.getParameter('sysparm_counterParCode');
            var counterSettAccNum = this.getParameter('sysparm_counterSettAccNum'); //new field
            var converAccSwitch = this.getParameter('sysparm_converAccSwitch'); //new field
            var accOfClient = this.getParameter('sysparm_accOfClient'); //new field
            var receiverBic = this.getParameter('sysparm_receiverBic'); //Receiver Bic MSSCUSTODY-7158 
            var deliverBic = this.getParameter('sysparm_deliverBic'); //Deliverer Bic MSSCUSTODY-7158 
            var buyerBic = this.getParameter('sysparm_buyerBic'); //buyer Bic MSSCUSTODY-7158 
            var sellerBic = this.getParameter('sysparm_sellerBic'); //seller Bic  MSSCUSTODY-7158
            var placeofSett = this.getParameter('sysparm_placeofSett');
            var amendChargesType = this.getParameter('sysparm_amendChargesType');
            var amendChargesCCY = this.getParameter('sysparm_amendChargesCCY');
            var amendChargesAMT = this.getParameter('sysparm_amendChargesAMT');
            var amendNSSC = this.getParameter('sysparm_amendNSSC');
            var amendsiPuposeCode = this.getParameter('sysparm_amendsiPuposeCode'); //MSSCUSTODY-7294
            var amendDataSourceScheme = this.getParameter('sysparm_amendDataSourceScheme'); //MSSCUSTODY-7294
            var amendPropriatryCode = this.getParameter('sysparm_amendPropriatryCode'); //MSSCUSTODY-7294
            var amendIndISS = this.getParameter('sysparm_amendIndIss'); //MSSCUSTODY-7747
            var amendSwh = this.getParameter('sysparm_amendSwh'); //MSSCUSTODY-7515
            var amendFa = this.getParameter('sysparm_amendfa'); //MSSCUSTODY-8151
            var amendSwitchRef = this.getParameter('sysparm_amendSwitchRef'); //MSSCUSTODY-7240



            //inputs from bulk

            if (bulkID == '') {

                //Creation of Bulk
                var createBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
                createBulk.initialize();
                createBulk.short_description = 'Trade Amendment ';
                createBulk.bulk_type = 'automated_task';
                createBulk.outcome = taskOutcome;
                createBulk.assignment_group = assignmentGrp;
                createBulk.assigned_to = gs.getUserID();
                createBulk.owning_business = tradeMarket;
                createBulk.current_maker_assignee = gs.getUserID();
                createBulk.active_trade_count = 1;
                createBulk.state = 3;
                //populating fields
                createBulk.security_id_sec_id = securityID;
                createBulk.amend_trade_date = tradeDate;
                createBulk.settlement_date = settlementDate;
                createBulk.amend_deal_price = dealPrice;
                createBulk.amend_deal_currency = dealCurrency;
                createBulk.amend_settlement_currency = settlementCurrency;
                createBulk.amend_settlement_amount = settlementAmount;
                createBulk.counterparty_reference = counterPartyRef;
                createBulk.customer_reference = cusRef;
                createBulk.amend_location_code = locCode;
                createBulk.amend_hmi_indicator = hmiIndicator;
                createBulk.amend_script_hold_indicator = scripholIndicator;
                createBulk.amend_cash_hold_indicator = cashHoldIndicator;
                createBulk.amend_gdi_indicator = gdiIncidcator;
                createBulk.amend_payment_method = payMethod;
                createBulk.amend_switch_indicator = switchIndicator;
                createBulk.amend_switch_account = switchAcc;
                createBulk.amend_suspense_account_number = susAccNum; //new field
                createBulk.amend_counterparty_code = counterParCode;
                createBulk.amend_counterparty_settlement_account_number = counterSettAccNum; //new field
                createBulk.amend_convert_to_account_switching = converAccSwitch; //new field
                createBulk.amend_a_c_of_client = accOfClient; //new field
                createBulk.amend_receiver_custodian_bic = receiverBic; //Receiver Bic MSSCUSTODY-7158
                createBulk.amend_deliverer_custodian_bic_receiver_custodian_bic = deliverBic; //Deliverer Bic MSSCUSTODY-7158
                createBulk.amend_buyer_bic = buyerBic; //buyer Bic MSSCUSTODY-7158
                createBulk.amend_seller_bic_buyer_bic = sellerBic; //seller Bic MSSCUSTODY-7158
                createBulk.amend_place_of_settlement_bic = placeofSett;
                createBulk.amend_charges_type = amendChargesType;
                createBulk.amend_charges_ccy = amendChargesCCY;
                createBulk.amend_charges_amt = amendChargesAMT;
                createBulk.amend_nssc = amendNSSC;
                createBulk.amend_si_purpose_code = amendsiPuposeCode; //MSSCUSTODY-7294
                createBulk.amend_data_source_scheme = amendDataSourceScheme; //MSSCUSTODY-7294
                createBulk.amend_propriaty_code = amendPropriatryCode; //MSSCUSTODY-7294
                createBulk.amend_iss = amendIndISS; //MSSCUSTODY-7747
                createBulk.amend_swh = amendSwh; //MSSCUSTODY-7515
                createBulk.amend_fa = amendFa; //MSSCUSTODY-8151
                createBulk.amend_trade_switch_reference = amendSwitchRef; //MSSCUSTODY-7240

                //populating fields
                createBulk.insert();
                //Creation of Bulk



                //updation of task with Bulk ID
                var createTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                createTask.get(tasksysID);
                createTask.bulk_id = createBulk.sys_id;
                createTask.outcome = taskOutcome;
                createTask.state = 3;
                createTask.update();
                //updation of task with Bulk ID

            } else {

                //updation of Bulk
                var updateBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
                updateBulk.get(bulkID);
                //populating fields
                updateBulk.security_id_sec_id = securityID;
                updateBulk.amend_trade_date = tradeDate;
                updateBulk.settlement_date = settlementDate;
                updateBulk.amend_deal_price = dealPrice;
                updateBulk.amend_deal_currency = dealCurrency;
                updateBulk.amend_settlement_currency = settlementCurrency;
                updateBulk.amend_settlement_amount = settlementAmount;
                updateBulk.counterparty_reference = counterPartyRef;
                updateBulk.customer_reference = cusRef;
                updateBulk.amend_location_code = locCode;
                updateBulk.amend_hmi_indicator = hmiIndicator;
                updateBulk.amend_script_hold_indicator = scripholIndicator;
                updateBulk.amend_cash_hold_indicator = cashHoldIndicator;
                updateBulk.amend_gdi_indicator = gdiIncidcator;
                updateBulk.amend_payment_method = payMethod;
                updateBulk.amend_switch_indicator = switchIndicator;
                updateBulk.amend_switch_account = switchAcc;
                updateBulk.amend_suspense_account_number = susAccNum; //new field
                updateBulk.amend_counterparty_code = counterParCode;
                updateBulk.amend_counterparty_settlement_account_number = counterSettAccNum; //new field
                updateBulk.amend_convert_to_account_switching = converAccSwitch; //new field
                updateBulk.amend_a_c_of_client = accOfClient; //new field
                updateBulk.amend_receiver_custodian_bic = receiverBic; //Receiver Bic MSSCUSTODY-7158
                updateBulk.amend_deliverer_custodian_bic_receiver_custodian_bic = deliverBic; //Deliverer Bic MSSCUSTODY-7158
                updateBulk.amend_buyer_bic = buyerBic; //buyer Bic MSSCUSTODY-7158
                updateBulk.amend_seller_bic_buyer_bic = sellerBic; //seller Bic MSSCUSTODY-7158
                updateBulk.amend_place_of_settlement_bic = placeofSett;
                updateBulk.amend_charges_type = amendChargesType;
                updateBulk.amend_charges_ccy = amendChargesCCY;
                updateBulk.amend_charges_amt = amendChargesAMT;
                updateBulk.amend_nssc = amendNSSC;
                updateBulk.amend_si_purpose_code = amendsiPuposeCode; //MSSCUSTODY-7294
                updateBulk.amend_data_source_scheme = amendDataSourceScheme; //MSSCUSTODY-7294
                updateBulk.amend_propriaty_code = amendPropriatryCode; //MSSCUSTODY-7294
                updateBulk.amend_iss = amendIndISS; //MSSCUSTODY-7747
                updateBulk.amend_swh = amendSwh; //MSSCUSTODY-7515
                updateBulk.amend_fa = amendFa; //MSSCUSTODY-8151
                updateBulk.amend_trade_switch_reference = amendSwitchRef; //MSSCUSTODY-7240
                //populating fields
                updateBulk.update();
                //Creation of Bulk


                //updation of task with Bulk ID
                var updateTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                updateTask.get(tasksysID);
                updateTask.outcome = taskOutcome;
                updateTask.state = 3;
                updateTask.update();
                //updation of task with Bulk ID

            }

        } catch (error) {
            gs.info("Error from AmendInputs x_hsb11_hsbc_mss_o.MSSAmendUtilsCore -  createBulkRecordForTradeAmend" + error.message);
        }

    },




    createBulkTest: function() {

        try {
            var tasksysID = this.getParameter('sysparm_ID');
            var testVal = this.getParameter('sysparm_bulkVal');

            gs.info('amend vals ' + testVal);

            var createBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            createBulk.initialize();
            createBulk.short_description = 'Trade Amendment ';
            createBulk.bulk_type = 'automated_task';
            createBulk.outcome = 'Amend Trade';
            createBulk.owning_business = "GC UK";
            createBulk.security_id_sec_id = testVal;
            createBulk.insert();
            gs.addInfoMessage('creeated from SI' + createBulk.number);

            var updateTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            updateTask.get(tasksysID);
            updateTask.bulk_id = createBulk.sys_id;
            updateTask.outcome = 'Amend Trade';
            updateTask.update();


            var updateBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            updateBulk.get(createBulk.sys_id);
            if (updateBulk.next()) {
                updateBulk.security_id_sec_id = testVal;
                updateBulk.update();
            }


            return createBulk.sys_id;

        } catch (error) {
            gs.info("Error from x_hsb11_hsbc_mss_o.MSSAmendUtilsCore - AmendInputs createBulkIDTest" + error.message);
        }

    },

    // MSSCUSTODY-5504
    createRecordWidgetInbound: function(requestData, payload) {

        try {

            var eventsArray = [];
            grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grWidget.initialize();
            grWidget.object_id = requestData.objectid;
            grWidget.object_version = requestData.objectversion;
            grWidget.object_type = requestData.objecttype;
            grWidget.object_id_type = requestData.objectidtype;
            grWidget.event_status = requestData.eventstatus;
            grWidget.setValue('event_date_time', requestData.eventdatetime.replace('T', ' '));
            grWidget.source = requestData.source;
            grWidget.message_id = requestData.messageid;
            grWidget.event_type = requestData.eventtype;
            grWidget.additional_attributes = requestData.additionalattributes;
            grWidget.payload = JSON.stringify(payload);
            var widInbound = grWidget.insert(); // MSSCUSTODY-5504 : Insert Widget Inbound Record
            if (widInbound != '') {
                eventsArray.push({
                    'Status': '200',
                });
            } else {
                gs.info('Script Include - MSSAmendUtilsCore :- Unknown exception while processing Amend Request ');
                eventsArray.push({
                    'Status': '400',
                    'Message': 'Some Error Occurred'
                });
            }
            return eventsArray;
        } catch (e) {
            gs.info('Script Include - MSSAmendUtilsCore :- Unknown exception while processing Amend Request ' + e.message);
            eventsArray.push({
                'Status': '400',
                'Message': 'Error message : ' + e.message,
            });
            return eventsArray;
        }

    },




    getTradeFieldvaluesForBulk: function() { //Prepopulate Functionality

        try {

            //This method is to prepropulate the amend fields for automated task when the outcome is selected as Amend related outcomes
            //Once the form is submitted, the below method executes creating a culk and associating the responses provided by user to bulk record


            /*Artifacts Included:
			1) Client Script: MSS Bulk Prepopulate Amend from Trade
			2) Script Include: x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
			3) Script Include: x_hsb11_hsbc_mss_o.MSSAmendUtilsCore - getTradeFieldvaluesForBulk
			4) System Property: x_hsb11_mss_c_proc.enableautomatedamend.market
			5) System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes
			*/
            var bulkID = this.getParameter('sysparm_bulkID');

            var getBulkData = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            getBulkData.get(bulkID);
            var tradeCount = parseInt(getBulkData.active_trade_count);
            if (tradeCount > 1) { //execution only limitd to single bulk trade
                return false;
            }


            var getTaskData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getTaskData.addEncodedQuery('bulk_id.sys_idSTARTSWITH' + bulkID + '^trade_task_type=Maker^active=true'); //executes only if a active maker task is available
            getTaskData.query();
            if (getTaskData.next()) {
                var tradeID = getTaskData.trade_id.sys_id;
                var taskStatus = getTaskData.active;
            }


            if (taskStatus) { //check for active maker task

                var amendInputs = {};
                var getTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                getTradeData.get(tradeID);

                var tradefieldValues = ['security_id', 'trade_date', 'settlement_date', 'deal_price', 'deal_price_currency', 'settlement_amount_currency', 'settlement_amount', 'counterparty_reference', 'customer_reference', 'location_code', 'hold_matched_si_indicator', 'script_hold_indicator', 'cash_hold_indicator', 'gdi_indicator', 'cash_payment_method', 'switch_indicator', 'switch_account', 'counterparty_code', 'receiver_deliverer_custodian_bic', 'buyer_seller_bic', 'place_of_settlement_95a_qualifier_pset', 'a_c_of_client', 'convert_to_account_switching', 'counterparty_settlement_account_number', 'suspense_account_number', 'amend_charges_type', 'amend_charges_ccy', 'amend_charges_amt', 'nssc']; //populate amend values
                var requestHeaders = ['securityID', 'tradeDate', 'settlementDate', 'dealPrice', 'dealCurrency', 'settlementCurrency', 'settlementAmount', 'counterPartyRef', 'cusRef', 'locCode', 'hmiIndicator', 'scripholIndicator', 'cashHoldIndicator', 'gdiIncidcator', 'payMethod', 'switchIndicator', 'switchAcc', 'counterParCode', 'delivererCusBic', 'sellBuyBic', 'placeofSett', 'accOfClient', 'converAccSwitch', 'counterSettAccNum', 'susAccNum', 'amendChargesType', 'amendChargesCCY', 'amendChargesAmt', 'amendNSSC']; // request body header

                for (i = 0; i < tradefieldValues.length; i++) {

                    if ((getTradeData.getValue(tradefieldValues[i]) != '') && (getTradeData.getValue(tradefieldValues[i]) != null) && (getTradeData.getValue(tradefieldValues[i]) != undefined)) {
                        var requestHeadersname = requestHeaders[i];
                        var trdValue = getTradeData.getValue(tradefieldValues[i]);
                        amendInputs[requestHeadersname] = trdValue;

                    }
                }

                return JSON.stringify(amendInputs);
            } else {
                return false;
            }

        } catch (error) {
            gs.info("Error from AmendInputs x_hsb11_hsbc_mss_o.MSSAmendUtilsCore - getTradeFieldvaluesForBulk" + error.message);
        }


    },

    createRequestBodyForRemoteTableAPICall: function(generatedQuery, v_table) {

        try {
            //MSSCUSTODY-5855
            var requestBody = {};

            var query = generatedQuery.split('^');

            var inputText;

            for (var i = 0; i < query.length; i++) {

                inputText = query[i].match(/(?:STARTSWITH|CONTAINS)([a-zA-Z0-9-]*)/);

                if (inputText && inputText[1].length >= 3) {
                    if (query[i].indexOf('security_id') > -1 || query[i].indexOf('security_name') > -1 || query[i].indexOf('isin') > -1 || query[i].indexOf('local_market_code') > -1) {
                        if (query[i].indexOf('security_id') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.instrumentAlternateGhssIdentifier = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.instrumentAlternateGhssIdentifier = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('security_name') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.instrumentShortName = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.instrumentShortName = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('isin') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.isin = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.isin = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('local_market_code') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.instrumentAlternateIdentifierLocalSecurityCode = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.instrumentAlternateIdentifierLocalSecurityCode = '*' + inputText[1].toUpperCase() + '*';
                            }
                        }
                    } else if (query[i].indexOf('switch_account') > -1 || query[i].indexOf('switch_account_name') > -1) {
                        if (query[i].indexOf('switch_account_name') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.safekeepingAccountShortName = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.safekeepingAccountShortName = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('switch_account') > -1) {
                            if (inputText && inputText[1].length >= 4) {
                                if (query[i].indexOf('STARTSWITH') > -1) {
                                    requestBody.safekeepingAccountIdentification = inputText[1].toUpperCase() + '*';
                                } else if (query[i].indexOf('CONTAINS') > -1) {
                                    requestBody.safekeepingAccountIdentification = '*' + inputText[1].toUpperCase() + '*';
                                }
                            } else {
                                return false;
                            }
                        }
                    } else if (query[i].indexOf('counterparty_code') > -1 || query[i].indexOf('bic') > -1 || query[i].indexOf('counterparty_name') > -1) {
                        if (query[i].indexOf('counterparty_code') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.partyAlternateGhssIdentifier = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.partyAlternateGhssIdentifier = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('bic') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.bic = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.bic = '*' + inputText[1].toUpperCase() + '*';
                            }
                        } else if (query[i].indexOf('counterparty_name') > -1) {
                            if (query[i].indexOf('STARTSWITH') > -1) {
                                requestBody.partyName = inputText[1].toUpperCase() + '*';
                            } else if (query[i].indexOf('CONTAINS') > -1) {
                                requestBody.partyName = '*' + inputText[1].toUpperCase() + '*';
                            }
                        }
                    }
                }
            }

            if (JSON.stringify(requestBody) != '{}') {
                var siteCode = gs.getSession().getClientData('siteCode');
                requestBody.siteCode = siteCode;
                this.callRemoteTableAPI(JSON.stringify(requestBody), v_table);
            }

            return false;

        } catch (error) {
            gs.info('Unexpected Error in x_hsb11_hsbc_mss_o.MSSAmendUtilsCore - createRequestBodyForRemoteTableAPICall : ' + error.message);
        }

    },

    callRemoteTableAPI: function(requestBody, v_table) {
        try {
            // MSSCUSTODY-5855
            var requestbody = JSON.parse(requestBody);
            var mssRemoteTableOnDemandenv;
            var mssRemoteTableOnDemandToken = gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token');
            var response;
            var responseBody;
            var responseObj;
            var endSleep;

            var request = new sn_ws.RESTMessageV2('MSS Remote Table Ondemand API Send', 'Get Remote Table Records');
            request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', mssRemoteTableOnDemandToken);
            request.setQueryParameter('siteCode', requestbody.siteCode);

            if ('instrumentAlternateGhssIdentifier' in requestbody || 'instrumentShortName' in requestbody || 'isin' in requestbody || 'instrumentAlternateIdentifierLocalSecurityCode' in requestbody) {

                mssRemoteTableOnDemandenv = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'instruments';
                request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', mssRemoteTableOnDemandenv);
                request.setQueryParameter('instrumentAlternateGhssIdentifier', requestbody['instrumentAlternateGhssIdentifier'] ? requestbody['instrumentAlternateGhssIdentifier'] : '');
                request.setQueryParameter('instrumentShortName', requestbody['instrumentShortName'] ? requestbody['instrumentShortName'] : '');
                request.setQueryParameter('isin', requestbody['isin'] ? requestbody['isin'] : '');
                request.setQueryParameter('instrumentAlternateIdentifierLocalSecurityCode', requestbody['instrumentAlternateIdentifierLocalSecurityCode'] ? requestbody['instrumentAlternateIdentifierLocalSecurityCode'] : '');
                response = request.execute();
                responseBody = response.getBody();
