    amendResetAllButtonVisibility: function(bulkID_sysID) { //MSSCUSTODY-5852 reset button visibility

        try {

            var grbulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            grbulk.get(bulkID_sysID);
            var bulkState = parseInt(grbulk.getValue('state'));
            var activeTradeCount = parseInt(grbulk.active_trade_count);
            if ((activeTradeCount == 1) && ((bulkState == 1) || (bulkState == 2))) {
                var buttonVisibility = false;


                if (grbulk.bulk_type == 'manual_task') { // check if the bulk type is manual

                    var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); //retrived the bulk record attributes
                    grTask.addEncodedQuery('bulk_id.sys_idSTARTSWITH' + bulkID_sysID + '^trade_task_type=Maker^active=true');
                    grTask.query();

                    if (grTask.next()) {
                        var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                        grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + grTask.trade_id.owning_business + '^ctac_code=' + grTask.trade_id.trade_lifecycle_status);
                        grBulkEvents.query();
                        if (grBulkEvents.next()) {
                            if (grBulkEvents.trade_amend.toString() == 'true') {
                                buttonVisibility = true;
                            }
                        }
                    }

                    return buttonVisibility;

                }

                if (grbulk.bulk_type == 'automated_task') { // check if the bulk type is automated
                    var automatedTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); //retrived the bulk record attributes
                    automatedTask.addEncodedQuery('bulk_id.sys_idSTARTSWITH' + bulkID_sysID + '^trade_task_type=Maker^active=true');
                    automatedTask.query();
                    if (automatedTask.next()) {
                        var outComeMapping = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_outcome_mapping');
                        outComeMapping.addEncodedQuery('trade_template_id.sys_idSTARTSWITH' + automatedTask.trade_task_template_id.sys_id + '^outcomeLIKEamend');
                        outComeMapping.query();
                        while (outComeMapping.next()) {
                            buttonVisibility = true;
                        }

                    }

                    return buttonVisibility;
                }

            } else {
                return false;
            }

        } catch (ex) {
            gs.info('Erro from amendResetAllButtonVisibility Bulk ' + ex);
        }


    },
    // MSSCUSTODY-5853 - Added function for updating Outbound Record on receiving EL RPA Amend inbound
    updateOutboundRecord: function(payload, taskSysID, status, ghssMessage, rpaMessage, eventDate) {
        try {
            var amendRec = 'sn_task.sys_id=' + taskSysID + '^state=processing_rpa';
            var taskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            taskGR.get(taskSysID);

            var outboundGR = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
            outboundGR.addEncodedQuery(amendRec);
            outboundGR.setLimit(1);
            outboundGR.query();

            if (outboundGR.next()) {
                outboundGR.response_body = JSON.stringify(payload);
                outboundGR.response_date = eventDate;
                if (status.toString() == 'GHSS_AMEND_SUCCESS') {
                    outboundGR.state = "processed_rpa";
                    taskGR.work_notes = ' GHSS Amend Success - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                    taskGR.state = 3; // Set state to close complete

                } else if (status.toString() == 'GHSS_APPRVL_REQUIRED') {
                    outboundGR.state = "processed_rpa";
                    taskGR.work_notes = ' GHSS Appoval Required - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                    taskGR.state = 6; // Set state to awaiting info

                } else if (status.toString() == 'GHSS_AMEND_FAIL') {
                    outboundGR.state = "error_rpa";
                    taskGR.work_notes = ' GHSS Amend Fail - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                    taskGR.state = 4; // Set state to closed rejected

                } else if (status.toString() == 'GHSS_APPROVE_FAIL') {
                    outboundGR.state = "error_rpa";
                    taskGR.work_notes = ' GHSS Approve Fail - RPA message: ' + rpaMessage + ' GHSS message: ' + ghssMessage;
                    taskGR.state = 8; // Set state to reviewed

                }
                outboundGR.update(); // Update Outbound record
                taskGR.update(); // Update task record

            }
        } catch (e) {
            gs.error('Error in updating GHSS outbound record: ' + e.message);
        }
    },

