    fetchEligibleFieldsForBulkAmend: function() {

        try {
            var bulkID = this.getParameter('sysparm_bulkid');
            // MSSCUSTODY 5985 - Function created for fields to consider based on the configuration matrix. 
            // This function is called in client scipt - Show Amend Fields in Bulk Form
            var fields = [
                'amend_trade_date',
                'settlement_date',
                'customer_reference',
                'security_id_sec_id',
                'amend_security_id_sec_id_ref',
                'amend_location_code',
                'amend_gdi_indicator',
                'amend_hmi_indicator​',
                'amend_script_hold_indicator',
                'amend_cash_hold_indicator',
                'counterparty_reference',
                'amend_payment_method',
                'amend_counterparty_code',
                'amend_counterparty_code_ref',
                'amend_counterparty_settlement_account_number',
                'amend_a_c_of_client',
                'amend_deliverer_custodian_bic_receiver_custodian_bic',
                'amend_seller_bic_buyer_bic',
                'amend_place_of_settlement_bic',
                'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
                'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
                'amend_charges_type',
                'amend_charges_ccy',
                'amend_charges_amt',
                'amend_swh', // MSSCUSTODY-7989 - Added SWH
                'amend_fa', // MSSCUSTODY-8183
                'amend_iss' // MSSCUSTODY-8183
            ];

            var trades = [];
            var transaType = [];
            var switchInc = [];
            var legstatus = [];
            var uniqueArray = new global.ArrayUtil();
            var finalResult = {};
            var tradeDataErrors = [];

            var hiddenFields = []; // Array to collect fields that need to be hidden
            var nonEditableFields = []; // Array to collect fields that needs to be non-editable

            // Fetch all maker tasks linked to the bulk
            var bul = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            bul.addEncodedQuery('bulk_id.sys_idLIKE' + bulkID + '^trade_task_type=Maker^active=true');
            bul.query();
            while (bul.next()) {
                trades.push(bul.trade_id + '');
            }




            if (trades.length > 0) {


                // Fetch transaction type, switch indicator and legacy status for each trade
                for (var i = 0; i < trades.length; i++) {
                    var grTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    grTrade.get(trades[i]);


                    //Transaction Type of Trade
                    if ((grTrade.getValue('transaction_type') != null) && (grTrade.getValue('transaction_type') != undefined) && (grTrade.getValue('transaction_type') != '')) {
                        transaType.push(grTrade.getValue('transaction_type').toString());
                    }

                    //Switch Indicator Type of Trade
                    if ((grTrade.getValue('switch_indicator') != null) && (grTrade.getValue('switch_indicator') != undefined) && (grTrade.getValue('switch_indicator') != 'null')) {
                        switchInc.push(grTrade.getValue('switch_indicator'));
                    }
                    //Legacy Status Type of Trade
                    if ((grTrade.getValue('legacy_status').toString() === 'UNEX') && (grTrade.getValue('legacy_status') != null) && (grTrade.getValue('legacy_status') != undefined) && (grTrade.getValue('legacy_status') != 'null')) {
                        legstatus.push(tradeLegacyPrevStatus); // For UNEX legacy status, consider value of Previous Legacy Status field.
                    } else {

                        if ((grTrade.getValue('legacy_status') != null) && (grTrade.getValue('legacy_status') != undefined) && (grTrade.getValue('legacy_status') != 'null')) {
                            legstatus.push(grTrade.getValue('legacy_status'));
                        }
                    }
                }



                // Get unique values for transaction type, switch indicator and legacy status
                var uniqueTransType = uniqueArray.unique(transaType);
                var uniqueSwitchIndicators = uniqueArray.unique(switchInc);
                var uniqueLegacyStatus = uniqueArray.unique(legstatus);



                if ((uniqueTransType.length != 0) && (uniqueSwitchIndicators.length != 0) && (uniqueLegacyStatus.length != 0)) { //checking if anyof the fundamental value is available or not


                    // Stage 1: Filter fields based on transaction type

                    var level1Result = fields.slice(); // Start with all fields
                    var isValidRVPDVPTrades;
                    var isValidDVPDFPTrades;
                    var isValidRVPTrades;

                    var transTypeRVPDVP = ['amend_counterparty_settlement_account_number', 'amend_payment_method', 'amend_settlement_amount']; // Only for RVP DVP
                    var transTypeDVPDFP = ['amend_script_hold_indicator']; //Only for DVP DFP
                    var transTypeRVP = ['amend_cash_hold_indicator', 'amend_fa']; // Only for RVP

                    // Iterate through unique transaction types to check if other than RVP or DVP
                    for (var j = 0; j < uniqueTransType.length; j++) {
                        if ((uniqueTransType[j] == 'RVP')) {
                            isValidRVPDVPTrades = true;

                        } else if ((uniqueTransType[j] == 'DVP')) {
                            isValidRVPDVPTrades = true;
                        } else {
                            isValidRVPDVPTrades = false;
                            break;
                        }
                    }

                    // Iterate through unique transaction types to check if other than DVP or DFP
                    for (var l = 0; l < uniqueTransType.length; l++) {
                        if ((uniqueTransType[l] == 'DVP')) {
                            isValidDVPDFPTrades = true;
                        } else if (uniqueTransType[l] == 'DFP') {
                            isValidDVPDFPTrades = true;
                        } else {
                            isValidDVPDFPTrades = false;
                            break;
                        }
                    }

                    // Iterate through unique transaction types to check if other than RVP
                    for (var m = 0; m < uniqueTransType.length; m++) {
                        if (uniqueTransType[m] == 'RVP') {
                            isValidRVPTrades = true;
                        } else {
                            isValidRVPTrades = false;
                            break;
                        }
                    }


                    // If any transaction check if other than RVP or DVP, remove stage 1 fields
                    if (isValidRVPDVPTrades.toString() == 'false') {
                        hiddenFields = hiddenFields.concat(transTypeRVPDVP); // Add stage 1 removed fields to hiddenFields
                        level1Result = uniqueArray.diff(level1Result, transTypeRVPDVP);
                    }
                    // If any transaction check if other than DVP or DFP, remove stage 1 fields
                    if (isValidDVPDFPTrades.toString() == 'false') {
                        hiddenFields = hiddenFields.concat(transTypeDVPDFP); // Add stage 1 removed fields to hiddenFields
                        level1Result = uniqueArray.diff(level1Result, transTypeDVPDFP);
                    }
                    // If any transaction check if other than RVP, remove stage 1 fields
                    if (isValidRVPTrades.toString() == 'false') {
                        hiddenFields = hiddenFields.concat(transTypeRVP); // Add stage 1 removed fields to hiddenFields
                        level1Result = uniqueArray.diff(level1Result, transTypeRVP);
                    }

                    // Stage 2: Filter fields based on switch indicator
                    var level2Result = level1Result.slice();
                    var isSwitchY = false; // Flag to check if any switch indicator is 'Y'

                    // Iterate through unique switch indicators
                    for (var k = 0; k < uniqueSwitchIndicators.length; k++) {
                        if (uniqueSwitchIndicators[k] === 'Y') {
                            isSwitchY = true;
                            break;
                        }
                    }

                    // Apply Stage 2 logic based on switch indicator
                    if (isSwitchY) {
                        var level2RemovalY = [
                            'counterparty_reference',
                            'amend_payment_method',
                            'amend_counterparty_code',
                            'amend_counterparty_code_ref',
                            'amend_counterparty_settlement_account_number'
                        ];
                        hiddenFields = hiddenFields.concat(level2RemovalY); // Add stage 2 removed fields for Switch Indicator = Y
                        level2Result = uniqueArray.diff(level2Result, level2RemovalY);
                    }

                    // Stage 3: Filter fields based on legacy status and switch indicator
                    uniqueLegacyStatus.forEach(function(status) {
                        // Handle CONF based on Switch Indicator
                        if (status === 'CONF') {
                            if (isSwitchY) {
                                // CONF (Switch)
                                nonEditableFields = nonEditableFields.concat([
                                    'security_id_sec_id',
                                    'amend_security_id_sec_id_ref',
                                    'amend_location_code',
                                    'amend_gdi_indicator',
                                    'amend_payment_method',
                                    'amend_counterparty_code',
                                    'amend_counterparty_code_ref',
                                    'amend_counterparty_settlement_account_number',
                                    'counterparty_reference'
                                ]);
                            } else {
                                // CONF (Non-Switch)
                                nonEditableFields = nonEditableFields.concat([
                                    'security_id_sec_id',
                                    'amend_security_id_sec_id_ref',
                                    'amend_location_code',
