                    finalResult.hiddenFields = uniqueArray.unique(hiddenFields);
                    finalResult.nonEditableFields = uniqueArray.unique(nonEditableFields);
                    finalResult.isSwitchY;


                } else {

                    //send all the elements to hide fields since the required inputs are not available
                    finalResult.hiddenFields = fields;
                    finalResult.nonEditableFields = fields;


                    if (uniqueTransType.length == 0) {
                        tradeDataErrors.push("Some of the linked trades do not hold a valid transaction type. <br\>");
                    }
                    if (uniqueSwitchIndicators.length == 0) {
                        tradeDataErrors.push("Some of the linked trades do not hold a valid Switch Indicator. <br\>");
                    }
                    if (uniqueLegacyStatus.length == 0) {
                        tradeDataErrors.push("Some of the linked trades do not hold a valid Legacy Status. <br\>");
                    }

                    gs.addErrorMessage(tradeDataErrors.toString());

                }

                return JSON.stringify(finalResult);

            }

        } catch (ex) {

            if (uniqueTransType.length == 0) {
                tradeDataErrors.push("Transaction Type of Trades hold empty values. <br\>");
            }
            if (uniqueSwitchIndicators.length == 0) {
                tradeDataErrors.push("Switch Indicator Type of Trades hold empty values. <br\>");
            }
            if (uniqueLegacyStatus.length == 0) {
                tradeDataErrors.push("Legacy Status of the trades hold empty values. <br\>");
            }
            gs.info('Failure from matrix for bulk ' + bulkID + " " + ex + " " + tradeDataErrors.toString());
        }
    },

    // MSSCUSTODY-8065 - Created function to check if any task linked to a bulk has any legacy status after CONF in amend
    bulkAmendHasAfterConfStatusTrade: function(bulkSysId) {
        var taskGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        taskGr.addQuery('bulk_id', bulkSysId);
        taskGr.query();
        while (taskGr.next()) {
            if ((taskGr.trade_id.legacy_status == 'CONF' && taskGr.trade_id.switch_indicator == 'Y') || taskGr.trade_id.legacy_status == 'CLRG' || taskGr.trade_id.legacy_status == 'MTCH' || taskGr.trade_id.legacy_status == 'STTS' || taskGr.trade_id.legacy_status == 'STTC') {
                return true;
            }
        }
        return false;
    },

    type: 'MSSAmendUtilsCore'
